contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address callee, bytes memory data, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint256 testBalBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;
        c.forward(callee, data); if (__ESBMC_reverted()) return;
        uint256 testBalAfter = address(this).balance;
        uint256 cBalAfter = address(c).balance;
        assert(testBalBefore == testBalAfter && cBalBefore == cBalAfter);
    }
}

